{
  "findings": [
    {
      "check_id": "CKV_AWS_389",
      "title": "Ensure AWS Auto Scaling group launch configuration doesn't have public IP address assignment enabled",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The resource explicitly sets associate_public_ip_address to true, which exposes instances directly to the internet. This increases the attack surface and is generally discouraged unless strictly necessary for specific use cases."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The metadata_options block is missing, defaulting to IMDSv1 being enabled alongside IMDSv2. Enforcing IMDSv2 (by setting http_tokens to 'required') mitigates Server-Side Request Forgery (SSRF) attacks that can steal instance credentials."
    },
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_launch_configuration.lc",
      "severity": "MEDIUM",
      "explanation": "The root_block_device configuration is missing, meaning the EBS volume attached to the instance will not be encrypted at rest by default. Encryption should be enforced to protect data confidentiality."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"lc\" {\n  name          = \"test_ecs\"\n  image_id      = data.aws_ami.amazon_linux.id\n  instance_type = \"t2.micro\"\n  lifecycle {\n    create_before_destroy = true\n  }\n  iam_instance_profile        = aws_iam_instance_profile.ecs_service_role.name\n  key_name                    = var.key_name\n  security_groups             = [aws_security_group.ec2-sg.id]\n  associate_public_ip_address = false\n  user_data                   = <<EOF\nsudo apt-get update\nsudo echo \"ECS_CLUSTER=${var.cluster_name}\" >> /etc/ecs/ecs.config\nEOF\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n\n  root_block_device {\n    encrypted = true\n  }\n}",
  "fix_summary": "Disabled public IP association by setting associate_public_ip_address to false. Added metadata_options to enforce IMDSv2 (http_tokens = required). Added root_block_device with encrypted = true to ensure EBS volumes are encrypted at rest."
}
